detail.script:
function parseDetail(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://godamh.com').replace(/\/$/, '');
  if (!html || typeof html !== 'string') html = '';
  if (html.length < 20 && ctx.url) { html = ''; }
  var stripTags = function(s){ return s.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim(); };
  var titleM = html.match(/<h1[^>]*class="[^"]*text-xl[^"]*"[^>]*>([\s\S]*?)<\/h1>/i);
  var title = titleM ? stripTags(titleM[1]) : '';
  title = title.replace(/(連載中|已完結|完結|連載)\s*$/, '').trim();
  var coverM = html.match(/<img[^>]*class="[^"]*object-cover[^"]*"[^>]*src="([^"]+)"/i);
  var cover = coverM ? coverM[1] : '';
  if (cover.indexOf('/') === 0) cover = baseUrl + cover;
  var descM = html.match(/<meta[^>]*name="description"[^>]*content="([^"]*)"/i) || html.match(/<meta[^>]*content="([^"]*)"[^>]*name="description"/i);
  var description = descM ? descM[1].trim() : '';
  var midM = html.match(/data-mid="(\d+)"/i);
  var mid = midM ? midM[1] : '';
  var authors = [];
  var authorUrls = [];
  var authorRe = /<a[^>]+href=["']([^"']*\/manga-author\/[^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
  var am;
  while ((am = authorRe.exec(html)) !== null) {
    var aHref = am[1];
    if (aHref.indexOf('/') === 0) aHref = baseUrl + aHref;
    var aName = stripTags(am[2]).replace(/[,\s]*$/, '').trim();
    if (aName && authors.indexOf(aName) < 0) {
      authors.push(aName);
      authorUrls.push(aHref);
    }
  }
  var author = authors.length > 0 ? authors.join(', ') : '';
  var authorUrl = authorUrls.length > 0 ? authorUrls.join(',') : '';
  var tags = [];
  var tagUrls = [];
  var tagRe = /<a[^>]+href=["']([^"']*\/manga-(?:tag|genre)\/[^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
  var tm;
  while ((tm = tagRe.exec(html)) !== null) {
    var tHref = tm[1];
    if (tHref.indexOf('/') === 0) tHref = baseUrl + tHref;
    var t = stripTags(tm[2]).replace(/[,\s]+/g, '').trim();
    if (t && tags.indexOf(t) < 0) {
      tags.push(t);
      tagUrls.push(tHref);
    }
  }
  var sm = html.match(/(連載中|已完結|完結)/);
  var status = sm ? sm[1] : '';
  // 更新时间：尝试多种常见标签
  var updatedAt = '';
  var uaRe = /(?:更新时间|更新于|最[后後]更新|更新时间)[：:]?\s*(\d{4}[-/]\d{1,2}[-/]\d{1,2}(?:\s+\d{1,2}:\d{1,2}(?::\d{1,2})?)?)/i;
  var uaM = html.match(uaRe);
  if (uaM) updatedAt = uaM[1].trim();
  var detailUrl = ctx.url || (baseUrl + '/manga/' + (ctx.id || ''));
  try { if (ctx.log) ctx.log('parseDetail: title=' + title + ', mid=' + mid + ', author=' + author + ', updatedAt=' + updatedAt); } catch(e){}
  return {
    id: ctx.id || '',
    title: title,
    cover: cover,
    description: description,
    author: author,
    authorUrl: authorUrl,
    status: status,
    tags: tags,
    tagUrls: tagUrls,
    mid: mid,
    updatedAt: updatedAt,
    detailUrl: detailUrl
  };
}

chapters.script:
function parseChapters(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://godamh.com').replace(/\/$/, '');
  if (!html || typeof html !== 'string' || html.length < 20) { return []; }
  var midM = html.match(/data-mid="(\d+)"/i);
  if (!midM) { try { if (ctx.log) ctx.log('parseChapters: no data-mid in HTML (len=' + html.length + ')'); } catch(e){} return []; }
  var mid = midM[1];
  var apiUrl = 'https://v2.apikk.top/api/manga/get?mid=' + mid + '&mode=all&t=' + Date.now();
  try { if (ctx.log) ctx.log('parseChapters: meta, mid=' + mid + ', apiUrl=' + apiUrl); } catch(e){}
  return { __meta: true, __fetchUrl: apiUrl, __processor: '__processChapters' };
}

// 同步处理函数：接收 Dart 预取的 API JSON 数据，返回章节列表。
// 由 ScriptResolver 在预取完成后自动调用，不入公共入口。
// 章节 id 采用 mid@chId 格式（与同源家族 bun 对齐），供 parseImages 拆分出数字 cid 调用 getinfo 接口。
function __processChapters(apiJson, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://godamh.com').replace(/\/$/, '');
  var data = apiJson && apiJson.data;
  if (!data || !data.chapters) { try { if (ctx.log) ctx.log('__processChapters: API returned no chapters'); } catch(e){} return []; }
  var mid = data.id ? String(data.id) : '';
  var results = [];
  for (var i = 0; i < data.chapters.length; i++) {
    var ch = data.chapters[i];
    var attrs = ch.attributes || {};
    var slug = attrs.slug ? attrs.slug : '';
    var title = attrs.title ? attrs.title : '';
    if (!slug || !ch.id) continue;
    // 尝试从 API 的各种时间字段中提取章节更新时间
    var updatedAt = '';
    var timeFields = ['updatedAt', 'createdAt', 'publishedAt', 'releaseAt', 'time', 'date', 'lastUpdated', 'updated_at', 'created_at'];
    for (var j = 0; j < timeFields.length; j++) {
      var key = timeFields[j];
      var v = attrs[key] || ch[key];
      if (v && typeof v === 'string' && v.trim().length > 0) {
        updatedAt = v.trim();
        break;
      }
    }
    results.push({ id: mid + '@' + ch.id, title: title, url: baseUrl + '/manga/' + (ctx.id || '') + '/' + slug, updatedAt: updatedAt });
  }
  try { if (ctx.log) ctx.log('__processChapters: found=' + results.length + ' chapters'); } catch(e){}
  return results;
}

images.script:
function decodeImages(raw) {
    var prefix = 'J7r';
    var suffix = 'nQ';
    var marker = 'kD';
    var keyB = 'W4s';
    var chunkSize = 7;
    var src = '_-9876543210abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    var dst = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
    if (!raw || typeof raw !== 'string' || raw.slice(0, prefix.length) !== prefix || raw.slice(-suffix.length) !== suffix) {
      return null;
    }
    var body = raw.slice(prefix.length, -suffix.length);
    var keyBLen = keyB.length;
    var markerLen = marker.length;
    var keyPos = body.indexOf(keyB);
    if (keyPos < 0) return null;
    var kdPositions = [];
    var searchFrom = 0;
    while (true) {
      var p = body.indexOf(marker, searchFrom);
      if (p < 0 || p >= keyPos) break;
      kdPositions.push(p);
      searchFrom = p + markerLen;
    }
    var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=';
    for (var idx = 0; idx < kdPositions.length; idx++) {
      var kdPos = kdPositions[idx];
      var cLen = keyPos - kdPos - markerLen;
      if (cLen < 0) continue;
      var tail = body.substr(keyPos + keyBLen);
      var part1 = body.substr(0, kdPos);
      var part3 = body.substr(kdPos + markerLen, cLen);
      var combined = tail + part1 + part3;
      var buf = '';
      for (var i = 0; i < combined.length; i += chunkSize) {
        var chunk = combined.substr(i, chunkSize);
        if (((i / chunkSize) | 0) % 2 === 1) {
          chunk = chunk.split('').reverse().join('');
        }
        buf += chunk;
      }
      var mapped = '';
      for (var j = 0; j < buf.length; j++) {
        var ch = buf[j];
        var sidx = src.indexOf(ch);
        mapped += sidx >= 0 ? dst[sidx] : ch;
      }
      var b64 = mapped.replace(/-/g, '+').replace(/_/g, '/');
      var pad = (4 - b64.length % 4) % 4;
      for (var p2 = 0; p2 < pad; p2++) b64 += '=';
      try {
        var out = '';
        for (var k = 0; k < b64.length; k += 4) {
          var e1 = chars.indexOf(b64.charAt(k));
          var e2 = chars.indexOf(b64.charAt(k + 1));
          var e3 = chars.indexOf(b64.charAt(k + 2));
          var e4 = chars.indexOf(b64.charAt(k + 3));
          out += String.fromCharCode((e1 << 2) | (e2 >> 4));
          if (e3 !== 64) out += String.fromCharCode(((e2 & 15) << 4) | (e3 >> 2));
          if (e4 !== 64) out += String.fromCharCode(((e3 & 3) << 6) | e4);
        }
        try { out = decodeURIComponent(escape(out)); } catch (e2) {}
        var parsed = JSON.parse(out);
        if (parsed && Array.isArray(parsed) && parsed.length > 0 && parsed[0] && parsed[0].url) {
          return parsed;
        }
      } catch (e) {
      }
    }
    return null;
  }


function parseImages(html, context) {
  var ctx = context || {};
  var mid = ctx.mid || '';
  var cid = ctx.cid || '';
  if (!mid || !cid) {
    var raw = ctx.chapterId || ctx.cid || ctx.id || '';
    if (raw && raw.indexOf('@') > 0) {
      var ids = raw.split('@');
      if (!mid) mid = ids[0];
      if (!cid) cid = ids[1];
    }
  }
  if (!mid || !cid) {
    var urlMatch = html.match(/\/manga\/[^/]+\/(\d+)-(\d+)-\d+/);
    if (urlMatch) { mid = urlMatch[1]; cid = urlMatch[2]; }
  }
  if (!mid || !cid) {
    var m3 = html.match(/data-mid=["'](\d+)["']/i);
    var m4 = html.match(/data-cid=["'](\d+)["']/i);
    if (m3) mid = m3[1];
    if (m4) cid = m4[1];
  }
  if (!mid || !cid) return [];
  var apiUrl = 'https://v2.apikk.top/api/v2/chapter/getinfo?m=' + mid + '&c=' + cid;
  return { __meta: true, __fetchUrl: apiUrl, __processor: '__processImages' };
}


function __processImages(apiJson, context) {
  var data = apiJson && apiJson.data;
  if (!data || !data.info || !data.info.images) return [];
  var raw = data.info.images.images;
  var images = null;
  if (typeof raw === 'string') {
    images = decodeImages(raw);
  } else if (Array.isArray(raw)) {
    images = raw;
  }
  if (!Array.isArray(images)) return [];
  var cdn = 'https://c-nd3-1.6wm.top';
  return images.map(function(item) {
    var u = item.url;
    if (!u) return '';
    if (u.startsWith('/')) u = cdn + u;
    else if (!/^https?:\/\//.test(u)) u = cdn + '/' + u;
    return u;
  }).filter(function(u) { return u && u.length > 0; });
}
